","export class ApiService {
 constructor(tableName) {
 this.tableName = tableName;
 this.baseUrl = `/api/now/table/${tableName}`;
 }

 async getAll(filters = {}) {
 try {
 const searchParams = new URLSearchParams(filters);
 searchParams.set('sysparm_display_value', 'all');

 const response = await fetch(`${this.baseUrl}?${searchParams.toString()}`, {
 method: 'GET',
 headers: {
 'Accept': 'application/json',
 'X-UserToken': window.g_ck
 }
 });

 if (!response.ok) {
 const error = await response.json();
 throw new Error(error.error?.message || 'Failed to fetch data');
 }

 const data = await response.json();
 return data.result || [];
 } catch (error) {
 console.error(`Error fetching from ${this.tableName}:`, error);
 throw error;
 }
 }

 async getById(sysId) {
 try {
 const response = await fetch(`${this.baseUrl}/${sysId}?sysparm_display_value=all`, {
 method: 'GET',
 headers: {
 'Accept': 'application/json',
 'X-UserToken': window.g_ck
 }
 });

 if (!response.ok) {
 const error = await response.json();
 throw new Error(error.error?.message || 'Failed to fetch record');
 }

 const data = await response.json();
 return data.result;
 } catch (error) {
 console.error(`Error fetching record from ${this.tableName}:`, error);
 throw error;
 }
 }

 async create(data) {
 try {
 const response = await fetch(this.baseUrl, {
 method: 'POST',
 headers: {
 'Content-Type': 'application/json',
 'Accept': 'application/json',
 'X-UserToken': window.g_ck
 },
 body: JSON.stringify(data)
 });

 if (!response.ok) {
 const error = await response.json();
 throw new Error(error.error?.message || 'Failed to create record');
 }

 const result = await response.json();
 return result.result;
 } catch (error) {
 console.error(`Error creating record in ${this.tableName}:`, error);
 throw error;
 }
 }

 async update(sysId, data) {
 try {
 const response = await fetch(`${this.baseUrl}/${sysId}`, {
 method: 'PATCH',
 headers: {
 'Content-Type': 'application/json',
 'Accept': 'application/json',
 'X-UserToken': window.g_ck
 },
 body: JSON.stringify(data)
 });

 if (!response.ok) {
 const error = await response.json();
 throw new Error(error.error?.message || 'Failed to update record');
 }

 const result = await response.json();
 return result.result;
 } catch (error) {
 console.error(`Error updating record in ${this.tableName}:`, error);
 throw error;
 }
 }

 async delete(sysId) {
 try {
 const response = await fetch(`${this.baseUrl}/${sysId}`, {
 method: 'DELETE',
 headers: {
 'Accept': 'application/json',
 'X-UserToken': window.g_ck
 }
 });

 if (!response.ok) {
 const error = await response.json();
 throw new Error(error.error?.message || 'Failed to delete record');
 }

 return true;
 } catch (error) {
 console.error(`Error deleting record from ${this.tableName}:`, error);
 throw error;
 }
 }

 // Helper method to extract field values (handles ServiceNow object fields)
 extractValue(field, type = 'display') {
 if (typeof field === 'object' && field !== null) {
 return type === 'display' ? field.display_value : field.value;
 }
 return field;
 }
}

export class StudentService extends ApiService {
 constructor() {
 super('x_1843073_institut_student');
 }

 async getActiveStudents() {
 return this.getAll({ 'sysparm_query': 'active=true^status=active' });
 }

 async getStudentsByYear(year) {
 return this.getAll({ 'sysparm_query': `active=true^year=${year}` });
 }
}

export class StaffService extends ApiService {
 constructor() {
 super('x_1843073_institut_staff');
 }

 async getActiveStaff() {
