 }

 async getStaffByDepartment(department) {
 return this.getAll({ 'sysparm_query': `active=true^department=${department}` });
 }
}

export class FeeService extends ApiService {
 constructor() {
 super('x_1843073_institut_fee');
 }

 async getPendingFees() {
 return this.getAll({ 'sysparm_query': 'active=true^payment_status=pending' });
 }

 async getOverdueFees() {
 return this.getAll({ 'sysparm_query': 'active=true^payment_status=overdue' });
 }
}

export class AttendanceService extends ApiService {
 constructor() {
 super('x_1843073_institut_attendance');
 }

 async getTodayAttendance() {
 const today = new Date().toISOString().split('T')[0];
 return this.getAll({ 'sysparm_query': `active=true^date=${today}` });
 }

 async getStudentAttendance(studentId, dateRange = {}) {
 let query = `active=true^student=${studentId}`;
 if (dateRange.start && dateRange.end) {
 query += `^dateBETWEEN${dateRange.start}@${dateRange.end}`;
 }
 return this.getAll({ 'sysparm_query': query });
 }
}

export class ResultService extends ApiService {
 constructor() {
 super('x_1843073_institut_result');
 }

 async getPublishedResults() {
 return this.getAll({ 'sysparm_query': 'active=true^published=true' });
 }

 async getStudentResults(studentId) {
 return this.getAll({ 'sysparm_query': `active=true^student=${studentId}` });
 }
}

export class NotificationService extends ApiService {
 constructor() {
 super('x_1843073_institut_notification');
 }

 async getActiveNotifications() {
 return this.getAll({ 
 'sysparm_query': 'active=true^sent=false^ORDERBYDESCpriority,created_date',
 'sysparm_limit': '20'
 });
 }

 async markAsSent(sysId) {
 return this.update(sysId, { 
 sent: true, 
 sent_date: new Date().toISOString() 
 });
 }
