export function BarChart({ data, title, color = '#3498db' }) {
 if (!data || data.length === 0) {
 return <div className="chart-placeholder">No data available</div>;
 }

 const maxValue = Math.max(...data.map(item => item.value));

 return (
 <div className="chart-container">
 <h4 className="chart-title">{title}</h4>
 <div className="bar-chart">
 {data.map((item, index) => (
 <div key={index} className="bar-item">
 <div className="bar-label">{item.label}</div>
 <div className="bar-container">
 <div 
 className="bar" 
 style={{ 
 width: `${(item.value / maxValue) * 100}%`,
 backgroundColor: color 
 }}
 >
 <span className="bar-value">{item.value}</span>
 </div>
 </div>
 </div>
 ))}
 </div>
 </div>
 );
}

export function PieChart({ data, title }) {
 if (!data || data.length === 0) {
 return <div className="chart-placeholder">No data available</div>;
 }

 const total = data.reduce((sum, item) => sum + item.value, 0);
 const colors = ['#3498db', '#e74c3c', '#2ecc71', '#f39c12', '#9b59b6', '#1abc9c'];

 let cumulativePercentage = 0;

 return (
 <div className="chart-container">
 <h4 className="chart-title">{title}</h4>
 <div className="pie-chart-container">
 <svg className="pie-chart" viewBox="0 0 200 200">
 {data.map((item, index) => {
 const percentage = (item.value / total) * 100;
 const angle = (percentage / 100) * 360;
 const startAngle = (cumulativePercentage / 100) * 360;

 const x1 = 100 + 80 * Math.cos((startAngle - 90) * Math.PI / 180);
 const y1 = 100 + 80 * Math.sin((startAngle - 90) * Math.PI / 180);
 const x2 = 100 + 80 * Math.cos((startAngle + angle - 90) * Math.PI / 180);
 const y2 = 100 + 80 * Math.sin((startAngle + angle - 90) * Math.PI / 180);

 const largeArcFlag = angle > 180 ? 1 : 0;
 const pathData = `M 100 100 L ${x1} ${y1} A 80 80 0 ${largeArcFlag} 1 ${x2} ${y2} Z`;

 cumulativePercentage += percentage;

 return (
 <path
 key={index}
 d={pathData}
 fill={colors[index % colors.length]}
 stroke="#fff"
 strokeWidth="2"
 />
 );
 })}
 </svg>
 <div className="pie-legend">
 {data.map((item, index) => (
 <div key={index} className="legend-item">
 <div 
 className="legend-color" 
 style={{ backgroundColor: colors[index % colors.length] }}
 ></div>
 <span>{item.label}: {item.value} ({((item.value / total) * 100).toFixed(1)}%)</span>
 </div>
 ))}
 </div>
 </div>
 </div>
 );
}

export function LineChart({ data, title, color = '#3498db' }) {
 if (!data || data.length === 0) {
 return <div className="chart-placeholder">No data available</div>;
 }

 const maxValue = Math.max(...data.map(item => item.value));
 const minValue = Math.min(...data.map(item => item.value));
 const range = maxValue - minValue || 1;

 const points = data.map((item, index) => {
 const x = (index / (data.length - 1)) * 280 + 10;
 const y = 150 - ((item.value - minValue) / range) * 130;
 return `${x},${y}`;
 }).join(' ');

 return (
 <div className="chart-container">
 <h4 className="chart-title">{title}</h4>
 <div className="line-chart">
 <svg viewBox="0 0 300 170">
 {/* Grid lines */}
 {[0, 1, 2, 3, 4].map(i => (
 <line
 key={i}
 x1="10"
 y1={20 + i * 32.5}
 x2="290"
 y2={20 + i * 32.5}
 stroke="#f0f0f0"
 strokeWidth="1"
 />
 ))}

 {/* Data line */}
 <polyline
 points={points}
 fill="none"
 stroke={color}
 strokeWidth="3"
 />

 {/* Data points */}
 {data.map((item, index) => {
 const x = (index / (data.length - 1)) * 280 + 10;
 const y = 150 - ((item.value - minValue) / range) * 130;
 return (
 <circle
 key={index}
 cx={x}
 cy={y}
 r="4"
 fill={color}
 />
 );
 })}
 </svg>
 <div className="line-chart-labels">
 {data.map((item, index) => (
 <span key={index} className="chart-label">{item.label}</span>
 ))}
 </div>
 </div>
 </div>
 );
}

export function StatCard({ title, value, subtitle, icon, color = '#3498db', trend }) {
 return (
 <div className="stat-card" style={{ borderLeftColor: color }}>
 <div className="stat-content">
 <div className="stat-header">
 <h3>{title}</h3>
 {icon && <div className="stat-icon" style={{ color }}>{icon}</div>}
 </div>
 <div className="stat-value" style={{ color }}>{value}</div>
 {subtitle && <div className="stat-subtitle">{subtitle}</div>}
 {trend && (
 <div className={`stat-trend ${trend.direction}`}>
 {trend.direction === 'up' ? '↗' : '↘'} {trend.value}
 </div>
 )}
 </div>
 </div>
 );
}

export function ProgressBar({ label, current, total, color = '#3498db' }) {
 const percentage = total > 0 ? (current / total) * 100 : 0;

 return (
 <div className="progress-container">
 <div className="progress-header">
 <span className="progress-label">{label}</span>
 <span className="progress-value">{current}/{total} ({percentage.toFixed(1)}%)</span>
 </div>
 <div className="progress-bar">
 <div 
 className="progress-fill" 
 style={{ 
 width: `${percentage}%`,
 backgroundColor: color 
 }}
 ></div>
 </div>
 </div>
 );
}","import React, { useState, useEffect } from 'react';
