 alerts: []
 });
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState(null);
 const [selectedTimeRange, setSelectedTimeRange] = useState('30'); // days

 // Service instances
 const studentService = new StudentService();
 const staffService = new StaffService();
 const feeService = new FeeService();
 const attendanceService = new AttendanceService();
 const resultService = new ResultService();
 const notificationService = new NotificationService();

 useEffect(() => {
 loadDashboardData();
 }, [selectedTimeRange]);

 const loadDashboardData = async () => {
 try {
 setLoading(true);
 setError(null);

 // Load all data in parallel
 const [students, staff, fees, attendance, results, notifications] = await Promise.all([
 studentService.getAll(),
 staffService.getAll(), 
 feeService.getAll(),
 attendanceService.getAll(),
 resultService.getAll(),
 notificationService.getActiveNotifications()
 ]);

 // Calculate overview statistics
 const overview = {
 totalStudents: students.filter(s => studentService.extractValue(s.active) === 'true').length,
 totalStaff: staff.filter(s => staffService.extractValue(s.active) === 'true').length,
 totalRevenue: fees
 .filter(f => feeService.extractValue(f.payment_status) === 'paid')
 .reduce((sum, f) => sum + parseFloat(feeService.extractValue(f.amount) || 0), 0),
 pendingFees: fees.filter(f => feeService.extractValue(f.payment_status) === 'pending').length,
 attendanceRate: calculateAttendanceRate(attendance)
 };

 // Prepare chart data
 const charts = {
 studentsByYear: generateStudentsByYearChart(students),
 feesByType: generateFeesByTypeChart(fees),
 attendanceByMonth: generateAttendanceByMonthChart(attendance),
 resultsByGrade: generateResultsByGradeChart(results),
 staffByDepartment: generateStaffByDepartmentChart(staff)
 };

 // Recent activities and alerts
 const recentActivities = generateRecentActivities(students, fees, results);
 const alerts = generateAlerts(fees, students, attendance);

 setDashboardData({
 overview,
 charts,
 recentActivities: recentActivities.slice(0, 10),
 alerts: alerts.slice(0, 5)
 });

 } catch (err) {
 setError('Failed to load dashboard data: ' + err.message);
 console.error('Admin dashboard error:', err);
 } finally {
 setLoading(false);
 }
 };

 const calculateAttendanceRate = (attendance) => {
 const presentCount = attendance.filter(a => 
 attendanceService.extractValue(a.status) === 'present'
 ).length;
 return attendance.length > 0 ? ((presentCount / attendance.length) * 100).toFixed(1) : 0;
 };

 const generateStudentsByYearChart = (students) => {
 const yearCounts = {};
 students.forEach(student => {
 const year = studentService.extractValue(student.year) || 'Unknown';
 yearCounts[year] = (yearCounts[year] || 0) + 1;
 });

 return Object.entries(yearCounts).map(([year, count]) => ({
 label: year === '1' ? '1st Year' : 
 year === '2' ? '2nd Year' :
 year === '3' ? '3rd Year' : 
 year === '4' ? '4th Year' :
 year === 'graduate' ? 'Graduate' : year,
 value: count
 }));
 };

 const generateFeesByTypeChart = (fees) => {
 const typeCounts = {};
 fees.forEach(fee => {
 const type = feeService.extractValue(fee.fee_type) || 'Unknown';
 const amount = parseFloat(feeService.extractValue(fee.amount) || 0);
 typeCounts[type] = (typeCounts[type] || 0) + amount;
 });

 return Object.entries(typeCounts).map(([type, amount]) => ({
 label: type.replace('_', ' ').toUpperCase(),
 value: Math.round(amount)
 }));
 };

 const generateAttendanceByMonthChart = (attendance) => {
 const monthCounts = {};
 attendance.forEach(record => {
 const date = attendanceService.extractValue(record.date);
 if (date) {
 const month = new Date(date).toLocaleString('default', { month: 'short' });
 const status = attendanceService.extractValue(record.status);
 if (status === 'present') {
 monthCounts[month] = (monthCounts[month] || 0) + 1;
 }
 }
 });

 return Object.entries(monthCounts)
 .sort((a, b) => new Date(a[0] + ' 1, 2024') - new Date(b[0] + ' 1, 2024'))
 .map(([month, count]) => ({
 label: month,
 value: count
 }));
 };

 const generateResultsByGradeChart = (results) => {
 const gradeCounts = {};
 results.forEach(result => {
 const grade = resultService.extractValue(result.grade) || 'Unknown';
 gradeCounts[grade] = (gradeCounts[grade] || 0) + 1;
 });

 return Object.entries(gradeCounts).map(([grade, count]) => ({
 label: grade.toUpperCase().replace('_', ''),
 value: count
 }));
 };

 const generateStaffByDepartmentChart = (staff) => {
 const deptCounts = {};
 staff.forEach(member => {
 const dept = staffService.extractValue(member.department) || 'Unknown';
 deptCounts[dept] = (deptCounts[dept] || 0) + 1;
 });

