 });
 });

 // Recent results published
 results.filter(r => resultService.extractValue(r.published) === 'true').slice(-5).forEach(result => {
 activities.push({
 type: 'result',
 message: `Result published for ${resultService.extractValue(result.subject)}`,
 time: resultService.extractValue(result.result_date),
 icon: '📊'
 });
 });

 return activities.sort((a, b) => new Date(b.time || 0) - new Date(a.time || 0));
 };

 const generateAlerts = (fees, students, attendance) => {
