import { NotificationService } from '../services/ApiService.js';

export default function NotificationCenter() {
 const [notifications, setNotifications] = useState([]);
 const [loading, setLoading] = useState(true);
 const [error, setError] = useState(null);

 const notificationService = new NotificationService();

 useEffect(() => {
 loadNotifications();
 }, []);

 const loadNotifications = async () => {
 try {
 setLoading(true);
 setError(null);
 const data = await notificationService.getAll();
 setNotifications(data);
 } catch (err) {
 setError('Failed to load notifications: ' + err.message);
 } finally {
 setLoading(false);
 }
 };

 const handleMarkAsSent = async (notification) => {
 try {
 const sysId = notificationService.extractValue(notification.sys_id, 'value');
 await notificationService.markAsSent(sysId);
 await loadNotifications();
 } catch (err) {
 setError('Failed to mark notification as sent: ' + err.message);
 }
 };

 if (loading) return <div className="loading">Loading notifications...</div>;

 return (
 <div className="notification-center">
 <div className="data-table">
 <div className="table-header">
 <h2>Notification Center</h2>
 <button className="btn">Create Notification</button>
 </div>

 {error && <div className="error">{error}</div>}

 <div className="table-content">
 {notifications.length === 0 ? (
 <p>No notifications found</p>
 ) : (
 <div className="notification-list">
 {notifications.map(notification => {
 const title = notificationService.extractValue(notification.title);
 const message = notificationService.extractValue(notification.message);
 const type = notificationService.extractValue(notification.notification_type);
 const priority = notificationService.extractValue(notification.priority);
 const audience = notificationService.extractValue(notification.target_audience);
 const sent = notificationService.extractValue(notification.sent);
 const createdDate = notificationService.extractValue(notification.created_date);

 return (
 <div 
 key={notificationService.extractValue(notification.sys_id, 'value')} 
 className={`notification-item priority-${priority}`}
 >
 <div className="notification-header">
 <h4>{title}</h4>
 <div className="notification-meta">
 <span className={`priority-badge ${priority}`}>
 {priority?.toUpperCase()}
 </span>
 <span className="type-badge">
 {type?.replace('_', ' ').toUpperCase()}
 </span>
 {sent === 'true' ? (
 <span className="sent-badge">SENT</span>
 ) : (
 <span className="pending-badge">PENDING</span>
 )}
 </div>
 </div>
 <p className="notification-message">{message}</p>
 <div className="notification-footer">
 <small>
 Target: {audience?.replace('_', ' ').toUpperCase()} | 
 Created: {createdDate}
 </small>
 <div className="notification-actions">
 <button className="btn-small">Edit</button>
 {sent !== 'true' && (
 <button 
 className="btn-small btn-success" 
 onClick={() => handleMarkAsSent(notification)}
 >
 Send Now
 </button>
 )}
 <button className="btn-small btn-danger">Delete</button>
 </div>
 </div>
 </div>
 );
 })}
 </div>
 )}
 </div>
 </div>
 </div>
 );
