import ResultManagement from './components/ResultManagement.jsx';
import NotificationCenter from './components/NotificationCenter.jsx';
import ChatBot from './components/ChatBot.jsx';
import './app.css';

export default function App() {
 const [currentView, setCurrentView] = useState('dashboard');
 const [notifications, setNotifications] = useState([]);

 useEffect(() => {
 // Load initial notifications
 loadNotifications();
 }, []);

 const loadNotifications = async () => {
 try {
 const response = await fetch('/api/now/table/x_1843073_institut_notification?sysparm_display_value=all&sysparm_limit=5&sysparm_query=active=true^sent=false^ORDERBYDESCpriority', {
 headers: {
 'Accept': 'application/json',
 'X-UserToken': window.g_ck
 }
 });
 if (response.ok) {
 const data = await response.json();
 setNotifications(data.result || []);
 }
 } catch (error) {
 console.error('Error loading notifications:', error);
 }
 };

 const renderCurrentView = () => {
 switch (currentView) {
 case 'dashboard':
 return <Dashboard />;
 case 'students':
 return <StudentManagement />;
 case 'staff':
 return <StaffManagement />;
 case 'fees':
 return <FeeManagement />;
 case 'attendance':
 return <AttendanceManagement />;
 case 'results':
 return <ResultManagement />;
 case 'notifications':
 return <NotificationCenter />;
 default:
 return <Dashboard />;
 }
 };

 return (
 <div className="institute-app">
 <header className="app-header">
 <h1>Institute Management System</h1>
 <nav className="main-nav">
 <button 
 className={currentView === 'dashboard' ? 'active' : ''}
 onClick={() => setCurrentView('dashboard')}
 >
 Dashboard
 </button>
 <button 
 className={currentView === 'students' ? 'active' : ''}
 onClick={() => setCurrentView('students')}
 >
 Students
 </button>
 <button 
 className={currentView === 'staff' ? 'active' : ''}
 onClick={() => setCurrentView('staff')}
 >
 Staff
 </button>
 <button 
 className={currentView === 'fees' ? 'active' : ''}
 onClick={() => setCurrentView('fees')}
 >
 Fee Management
 </button>
 <button 
 className={currentView === 'attendance' ? 'active' : ''}
 onClick={() => setCurrentView('attendance')}
 >
 Attendance
 </button>
 <button 
 className={currentView === 'results' ? 'active' : ''}
 onClick={() => setCurrentView('results')}
 >
 Results
 </button>
 <button 
 className={currentView === 'notifications' ? 'active' : ''}
 onClick={() => setCurrentView('notifications')}
 >
 Notifications ({notifications.length})
 </button>
 </nav>
 </header>

 <main className="app-main">
 {renderCurrentView()}
 </main>

 <ChatBot />
 </div>
 );
